                                    }
                                    if (result.status === 'failed') {
                                        throw result.error;
                                    }
                                    throw { tryAgain: result.tryAgain };
                                }
                            ),
                            abort,
                        };
                    }}
                />
            );
        });
    };

    return verify;
};

