        const Token = 'token-to-verify';
        const ApprovalURL = 'https://example.proton.me/approve';
        const ReturnHost = 'return.proton.me';
        const verifiedPayment = toTokenPaymentMethod(Token);

        const promise = getDefaultVerifyPayment(
            createModal,
            api
        )({
            mode: 'add-card',
            Payment,
            Token,
            ApprovalURL,
            ReturnHost,
        });

        expect(createModal).toHaveBeenCalledTimes(1);
        const modal = createModal.mock.calls[0][0];
        expect(modal.type).toBe(PaymentVerificationModal);
        expect(modal.props).toEqual(
            expect.objectContaining({
                mode: 'add-card',
                payment: Payment,
                token: Token,
                onProcess: expect.any(Function),
            })
        );

        modal.props.onSubmit(verifiedPayment);
        await expect(promise).resolves.toBe(verifiedPayment);
    });

    it('lets the modal process complete only for a chargeable token', async () => {
        const Token = 'token-to-verify';
        const verificationParams = {
            Token,
            ApprovalURL: 'https://example.proton.me/approve',
            ReturnHost: 'return.proton.me',
        };

        const successfulApi = jest.fn().mockResolvedValue({ Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });
        const successfulModal = jest.fn();
        const successfulVerification = getDefaultVerifyPayment(successfulModal, successfulApi)(verificationParams);
        const successfulElement = successfulModal.mock.calls[0][0];

        await expect(successfulElement.props.onProcess().promise).resolves.toBeUndefined();
        successfulElement.props.onSubmit(toTokenPaymentMethod(Token));
        await expect(successfulVerification).resolves.toEqual(toTokenPaymentMethod(Token));

        const failedApi = jest.fn().mockResolvedValue({ Status: PAYMENT_TOKEN_STATUS.STATUS_FAILED });
        const failedModal = jest.fn();
        const failedVerification = getDefaultVerifyPayment(failedModal, failedApi)(verificationParams);
        const failedElement = failedModal.mock.calls[0][0];

        await expect(failedElement.props.onProcess().promise).rejects.toThrow('Payment process failed');
        failedElement.props.onClose();
        await expect(failedVerification).rejects.toBeUndefined();

        const cancelledApi = jest.fn().mockResolvedValue({ Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING });
        const cancelledModal = jest.fn();
        const cancelledVerification = getDefaultVerifyPayment(cancelledModal, cancelledApi)(verificationParams);
        const cancelledElement = cancelledModal.mock.calls[0][0];
        const cancelledProcess = cancelledElement.props.onProcess();
        cancelledProcess.abort.abort();

        await expect(cancelledProcess.promise).rejects.toMatchObject({ tryAgain: undefined });
        cancelledElement.props.onClose();
        await expect(cancelledVerification).rejects.toBeUndefined();
    });
});

